const date = new Date();
const hour = date.getHours() + 1;

const timeCategories = {
  morning: {
    start: 6,
    end: 13,
    hColor: "#257cc3",
    mColor: "#1a5e94",
    borderColor: "#000d5fff"
  },
  noon: {
    start: 13,
    end: 19,
    hColor: "#f0f0f0",
    mColor: "#f0f0f0",
    borderColor: "#2f0000"
  },
  evening: {
    start: 19,
    end: 22,
    hColor: "#540000",
    mColor: "#440000",
    borderColor: "#2f0000"
  },
  night: {
    start: 22,
    end: 6,
    hColor: "#100000",
    mColor: "#100000",
    borderColor: "#100000",
  }
};

let theme = timeCategories.morning;

for (const [_, config] of Object.entries(timeCategories)) {
  let isInPeriod;

  if (config.start < config.end) {
    isInPeriod = hour >= config.start && hour < config.end;
  } else {
    // Handle overnight period (Night: 22:00 - 06:00)
    isInPeriod = hour >= config.start || hour < config.end;
  }

  if (isInPeriod) {
    theme = config;
    break;
  }
}

const manifest = {
  "meta": {
    "width": 64,
    "height": 64,
    "cacheLifespan": 5000
  },
  "slides": [
    {
      "duration": 3000,
      "drawings": [
        {
          "type": "rect",
          "posX": 0,
          "posY": 0,
          "width": 64,
          "height": 1,
          "color": theme.borderColor
        },
        {
          "type": "rect",
          "posX": 0,
          "posY": 63,
          "width": 64,
          "height": 1,
          "color": theme.borderColor
        },
        {
          "type": "rect",
          "posX": 0,
          "posY": 0,
          "width": 1,
          "height": 64,
          "color": theme.borderColor
        },
        {
          "type": "rect",
          "posX": 63,
          "posY": 0,
          "width": 1,
          "height": 64,
          "color": theme.borderColor
        },
        {
          "type": "text",
          "posX": 4,
          "posY": 3,
          "scale": 4,
          "prose": String(date.getHours()).padStart(2, "0"),
          "color": theme.hColor,
        },
        {
          "type": "text",
          "posX": 24,
          "posY": 33,
          "scale": 4,
          "prose": String(date.getMinutes()).padStart(2, "0"),
          "color": theme.mColor,
        },
      ]
    }
  ]
}

msg.payload = manifest;

return msg;
